<?php
namespace Tests\Feature; use App\Models\User; use App\Models\Exam; use App\Models\ExamCategory; use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase;
class ExperienceWorkflowTest extends TestCase {use RefreshDatabase; public function test_user_can_submit_experience_for_moderation():void{$user=User::create(['name'=>'Candidate','username'=>'candidate1','email'=>'candidate@example.com','password'=>'SecurePass123']);$category=ExamCategory::create(['name'=>'Railway','slug'=>'railway']);$exam=Exam::create(['name'=>'RRB Test','slug'=>'rrb-test','exam_category_id'=>$category->id,'status'=>'active']);$this->actingAs($user)->post('/experiences',['exam_id'=>$exam->id,'title'=>'My RRB exam experience','summary'=>'A short honest account','body'=>'I found the reasoning section moderate.','language'=>'en','intent'=>'submit'])->assertRedirect();$this->assertDatabaseHas('experiences',['user_id'=>$user->id,'exam_id'=>$exam->id,'status'=>'pending','verification_label'=>'candidate_reported']);} public function test_create_route_redirects_guests_to_login_instead_of_matching_experience_slug():void{$this->get('/experiences/create')->assertRedirect('/login');}}
